import React from 'react';
import { IconProps } from '@hexa-ui/icons';
import { config } from '@hexa-ui/theme';
import type * as Stitches from '@stitches/react';

import { StyledCarouselAction } from '../Carousel.styles';

type CarouselActionProps = {
  onClick: () => void;
  icon: React.FunctionComponent<IconProps>;
  css: Stitches.CSS<typeof config>;
};

export function CarouselAction({ icon, onClick, css, ...rest }: CarouselActionProps) {
  return (
    <StyledCarouselAction
      variant="secondary"
      elevation
      size="large"
      onClick={onClick}
      icon={icon}
      css={{ ...css, border: 0, background: '#F2F2F2' }}
      {...rest}
    />
  );
}
